-- Table: inventory_stock_movement
-- Source: accounting_admin_db.sql (5. Inventory)
--
-- One migration per table. Do not edit this file after it has been applied;
-- add a new migration for later schema changes.

CREATE TABLE IF NOT EXISTS inventory_stock_movement (
    id                   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    document_number      VARCHAR(50) NOT NULL UNIQUE,
    document_date        DATE NOT NULL,
    movement_type        VARCHAR(20) NOT NULL
                         CHECK (movement_type IN ('IN', 'OUT', 'ADJUST', 'TRANSFER')),
    reference_type       VARCHAR(50),
    reference_id         BIGINT,
    warehouse_id         BIGINT NOT NULL REFERENCES masterdata_warehouse(id),
    destination_warehouse_id BIGINT REFERENCES masterdata_warehouse(id),
    status               VARCHAR(20) NOT NULL DEFAULT 'draft'
                         CHECK (status IN ('draft', 'created', 'approved', 'rejected', 'pending', 'completed', 'reopen')),
    notes                TEXT,
    prepared_by          BIGINT REFERENCES masterdata_user(id),
    posted_by            BIGINT REFERENCES masterdata_user(id),
    posted_at            TIMESTAMPTZ,
    created_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK (
        (movement_type = 'TRANSFER' AND destination_warehouse_id IS NOT NULL)
        OR (movement_type <> 'TRANSFER' AND destination_warehouse_id IS NULL)
    )
);
